	}
	return null;
}

function titleAbove(nodes: ScreenNode[], bump: ScreenNode): string {
	const title = nodes
		.filter(
			(node) =>
				node.text &&
				node.y <= bump.y &&
				node.y > bump.y - 420 &&
				!node.text.includes("·") &&
				!/^[\d,]+원?$/.test(node.text) &&
				node.text !== "판매중" &&
				node.text !== "판매관리" &&
				node.text !== "원",
		)
		.sort((a, b) => b.y - a.y)[0];
	return title?.text ?? "";
}

