/**
 * 손을 멈춘 뒤 떼는 끌기. `input swipe`는 짧을수록 빨라 플링이 붙고, 수정 창에서 가격 칸을 건너뛰어 바닥까지 갔다.
 * 끝점에서 잠깐 머문 뒤 UP 해서 속도가 0으로 끝나게 한다. adb 왕복은 한 번이다.
 */
function drag(serial: string, exec: AdbExec, x: number, from: number, to: number) {
	const mid = Math.round((from + to) / 2);
	const steps = [
		`input motionevent DOWN ${x} ${from}`,
		`input motionevent MOVE ${x} ${mid}`,
		`input motionevent MOVE ${x} ${to}`,
		"sleep 0.25",
		`input motionevent UP ${x} ${to}`,
	].join(" && ");
	exec(["-s", serial, "shell", steps]);
	sleep(250);
}

function noteSkip(target: string, reason: string) {
	journal?.next({ cmd: "note", action: "건너뜀", reason, result: "화면을 움직이지 않음", target });
}

/** 한 단계의 시작·끝을 회차 시각으로 남긴다. 확정 전 중단은 이 단계 사이에서만 일어난다. */
function act(
	serial: string,
	record: { cmd: string; action: string; reason: string; target?: string; ok?: boolean },
	run: () => void,
	result: () => string,
	ok?: () => boolean,
) {
	const log = serial === journalSerial ? journal : null;
	const startMs = log?.now() ?? 0;
	run();
	const outcome = result();
	const endMs = log?.now() ?? 0;
	log?.next({ ...record, result: outcome, ...(ok ? { ok: ok() } : {}) }, { startMs, endMs });
}

/** 앞에 떠 있는 창(패키지/액티비티). 판매관리가 아닐 때 무엇이 가렸는지 로그에 남긴다. */
export function focusOf(serial: string, exec: AdbExec): string {
	const blob = exec(["-s", serial, "shell", "dumpsys", "window"]).stdout;
	return blob.match(/mCurrentFocus=Window\{\S+ \S+ ([^}\s]+)\}/)?.[1] ?? "모름";
}

function center(node: { x: number; y: number; w: number; h: number }) {
	return {
		x: Math.floor(node.x + node.w / 2),
		y: Math.floor(node.y + node.h / 2),
	};
}

function noConfirm(ops: ScreenOp[]): boolean {
	return ops.every((op) => op.kind !== "tap" || (op.label !== CONFIRM_BUMP && op.label !== CONFIRM_EDIT));
}

function fail(note: string, touched: boolean, ops: ScreenOp[] = []): PhoneRun {
	return {
		bumped: 0,
		pricedOnly: 0,
		skipped: 0,
		note,
		touched,
		confirmed: false,
		ops,
		stopped: false,
		logDir: journal?.dir,
	};
}

function stopped(bumped: number, pricedOnly: number, skipped: number, ops: ScreenOp[], byUser: boolean): PhoneRun {
	return {
		bumped,
		pricedOnly,
		skipped,
		note: byUser ? STOPPED_NOTE : "가격 칸이 승인값과 달라 확정하지 않았어요",
		touched: true,
		confirmed: false,
		ops,
		stopped: byUser,
		logDir: journal?.dir,
	};
}

function sleep(ms: number) {
	spawnSync("sleep", [(ms / 1000).toFixed(3)]);
}

